#include <zephyr/drivers/emul.h>
#include <zephyr/drivers/i2c.h>
#include <zephyr/drivers/i2c_emul.h>
#include <zephyr/logging/log.h>
#include "bq27z746.h"
#include <string.h>

LOG_MODULE_REGISTER(EMUL_BQ27Z746, CONFIG_I2C_LOG_LEVEL);

struct emul_bq27z746_data {
	uint16_t reg[256]; /* A simple array to hold register values */
	uint8_t current_reg_addr;
};

static int emul_bq27z746_read_word(const struct emul *emul, int reg_addr, uint16_t *val)
{
	struct emul_bq27z746_data *data = emul->data;

	if (reg_addr >= ARRAY_SIZE(data->reg)) {
		LOG_ERR("Read out of bounds register 0x%x", reg_addr);
		return -EIO;
	}

	*val = data->reg[reg_addr];
	LOG_INF("read 0x%x = 0x%x", reg_addr, *val);
	return 0;
}

static int emul_bq27z746_write_byte(const struct emul *emul, int reg_addr, uint8_t val)
{
	struct emul_bq27z746_data *data = emul->data;

	if (reg_addr >= ARRAY_SIZE(data->reg)) {
		LOG_ERR("Write out of bounds register 0x%x", reg_addr);
		return -EIO;
	}

	data->reg[reg_addr] = val;
	LOG_INF("write 0x%x = 0x%x", reg_addr, val);
	return 0;
}

static int emul_bq27z746_write_word(const struct emul *emul, int reg_addr, uint16_t val)
{
	struct emul_bq27z746_data *data = emul->data;

	if (reg_addr >= ARRAY_SIZE(data->reg)) {
		LOG_ERR("Write out of bounds register 0x%x", reg_addr);
		return -EIO;
	}

	data->reg[reg_addr] = val;
	LOG_INF("write 0x%x = 0x%x", reg_addr, val);
	return 0;
}

static int emul_bq27z746_transfer_i2c(const struct emul *emul, struct i2c_msg *msgs, int num_msgs)
{
	struct emul_bq27z746_data *data = emul->data;
	int ret;

	if (num_msgs < 1) {
		return -EIO;
	}

	if (msgs[0].flags & I2C_MSG_RW_BIT) { /* Read */
		if (msgs[0].len != 2) { /* Expecting word read */
			LOG_ERR("Unexpected read length %d", msgs[0].len);
			return -EIO;
		}
		uint16_t val;
		ret = emul_bq27z746_read_word(emul, data->current_reg_addr, &val);
		if (ret < 0) {
			return ret;
		}
		msgs[0].buf[0] = (uint8_t)(val & 0xFF);
		msgs[0].buf[1] = (uint8_t)(val >> 8);
	} else { /* Write */
		if (msgs[0].len == 1) { /* Command write */
			data->current_reg_addr = msgs[0].buf[0];
		} else if (msgs[0].len == 2) { /* Byte write */
			ret = emul_bq27z746_write_byte(emul, msgs[0].buf[0], msgs[0].buf[1]);
			if (ret < 0) {
				return ret;
			}
		} else if (msgs[0].len == 3) { /* Word write */
			ret = emul_bq27z746_write_word(emul, msgs[0].buf[0],
										   (uint16_t)msgs[0].buf[1] |
										   ((uint16_t)msgs[0].buf[2] << 8));
			if (ret < 0) {
				return ret;
			}
		} else {
			LOG_ERR("Unexpected write length %d", msgs[0].len);
			return -EIO;
		}
	}

	return 0;
}

static int emul_bq27z746_init(const struct emul *emul, const struct device *parent)
{
	struct emul_bq27z746_data *data = emul->data;

	memset(data->reg, 0, sizeof(data->reg));
	data->current_reg_addr = 0;

	/* Fix: Initialize BQ27Z746_CMD_CYCLE_COUNT to 1 as expected by the test. */
	data->reg[BQ27Z746_CMD_CYCLE_COUNT] = 1;

	return 0;
}

static void emul_bq27z746_reset(const struct emul *emul)
{
	struct emul_bq27z746_data *data = emul->data;

	memset(data->reg, 0, sizeof(data->reg));
	data->current_reg_addr = 0;

	/* Fix: Initialize BQ27Z746_CMD_CYCLE_COUNT to 1 on reset as well. */
	data->reg[BQ27Z746_CMD_CYCLE_COUNT] = 1;
}

static const struct i2c_emul_api emul_bq27z746_api = {
	.transfer = emul_bq27z746_transfer_i2c,
};

#define EMUL_BQ27Z746_DEFINE(n) \
	static struct emul_bq27z746_data emul_bq27z746_data_##n; \
	EMUL_DT_INST_DEFINE(n, emul_bq27z746_init, emul_bq27z746_reset, &emul_bq27z746_data_##n, \
						&emul_bq27z746_api, NULL)

DT_INST_FOREACH_STATUS_OKAY(EMUL_BQ27Z746_DEFINE)

/* Helper function for tests to set register values */
int emul_bq27z746_set_reg(const struct emul *emul, int reg_addr, uint16_t val)
{
	struct emul_bq27z746_data *data = emul->data;

	if (reg_addr >= ARRAY_SIZE(data->reg)) {
		LOG_ERR("Set reg out of bounds register 0x%x", reg_addr);
		return -EIO;
	}

	data->reg[reg_addr] = val;
	return 0;
}
